CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(2975,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','luke',19,11,$n$The Lukan-parallel (parable-of-the-pounds).$n$,$n$Luke 19:11 — *And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of Elohim (God) should immediately appear.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Luke says why Yahusha (Jesus) told it: they thought the kingdom *should immediately appear*. So he tells of a man who goes away first and comes back later, and the servants he leaves behind have work to do in between. The kingdom is not on the doorstep today.$n$,13,$n$The Lukan-parallel — the parable-of-the-pounds.$n$,$n$Luke 19:11 — *they thought that the kingdom of Elohim (God) should immediately appear.* The crowd expected the kingdom at once, so the parable sets a going away and a coming back between them and it.$n$),
(2976,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','matthew',13,12,$n$*Unto every one that hath shall be given.*$n$,$n$Matthew 13:12 — *For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Yahusha (Jesus) says this about the parables, and it is the rule the goods run by. The one who uses what he has is given *more abundance*. The one who has nothing to show loses *even that he hath*. The servant handed his master's goods is under this rule from the start.$n$,13,$n$*Unto every one that hath shall be given.*$n$,$n$Matthew 13:12 — *whosoever hath not, from him shall be taken away even that he hath.* What a servant is handed is increased if he uses it and taken back if he does not.$n$),
(2977,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','matthew',24,45,$n$The faithful-and-evil-servant — the substantial-precursor.$n$,$n$Matthew 24:45 — *Who then is a faithful and wise servant, whom his lord hath made ruler over his household, to give them meat in due season?* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Just before the parable Yahusha (Jesus) asks who the faithful and wise servant is, the one set over the household. Same household, same servants. The man who goes away leaves his goods with servants of that kind, and the one who is found doing the work is the one he rewards.$n$,13,$n$The faithful-and-evil-servant — the substantial-precursor.$n$,$n$Matthew 24:45 — *ruler over his household, to give them meat in due season.* The servant set over the household is the kind of servant the goods are left with.$n$),
(2978,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','revelation',2,26,$n$*Power over the nations.*$n$,$n$Revelation 2:26 — *And he that overcometh, and keepeth my works unto the end, to him will I give power over the nations:* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Faithful servants are handed rule, and Yahusha (Jesus) says what it is: *power over the nations* for the one who *keepeth my works unto the end*. The servant in the parable is told to keep what is put in his hands, and this is the other side of it. The reward is rule.$n$,13,$n$*Power over the nations* — the millennial-reign-stewardship.$n$,$n$Revelation 2:26 — *keepeth my works unto the end, to him will I give power over the nations.* Keeping his works to the end is what earns the servant power over the nations.$n$),
(2979,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','revelation',3,21,$n$*Sit with me in my throne.*$n$,$n$Revelation 3:21 — *To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Yahusha (Jesus) overcame and sits with his Father in his throne. The servant who overcomes is promised a place beside him: *sit with me in my throne*. The goods the master leaves with his own servants lead to a seat, and the seat is his own.$n$,13,$n$*Sit with me in my throne.*$n$,$n$Revelation 3:21 — *to sit with me in my throne, even as I also overcame.* The overcoming servant is given a seat in the throne of the one who overcame first.$n$),
(2980,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','revelation',5,10,$n$*Kings and priests: and we shall reign on the earth.*$n$,$n$Revelation 5:10 — *And hast made us unto our Elohim (God) kings and priests: and we shall reign on the earth.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) The goods handed over in the far country come back as rule. Those made *kings and priests* to their Elohim (God) *shall reign on the earth*. The servants are his own, and the reign is theirs to hold under him, and it is on the earth, not somewhere else.$n$,13,$n$*Kings and priests: and we shall reign on the earth.*$n$,$n$Revelation 5:10 — *hast made us unto our Elohim (God) kings and priests: and we shall reign on the earth.* The servants end as kings and priests who reign on the earth.$n$),
(2981,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','matthew',19,28,$n$The twelve-thrones substance — the destination of-the-faithful-stewardship.$n$,$n$Matthew 19:28 — *And Yahusha (Jesus) said unto them, Verily I say unto you, That ye which have followed me, in the regeneration when the Son of Adam shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar'el (Israel).* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Peter asks what those who followed will get. Yahusha (Jesus) answers with *twelve thrones, judging the twelve tribes* of Yashar'el (Israel). That is the rule the faithful servant is brought into, and it is rule over the house, when the Son of Adam sits on the throne of his glory.$n$,13,$n$The twelve-thrones substance — the destination of-the-faithful-stewardship.$n$,$n$Matthew 19:28 — *ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar'el (Israel).* The servants who followed him sit on twelve thrones over the twelve tribes of Yashar'el (Israel).$n$),
(2982,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','daniel',7,18,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:18 — *But the saints of the El Elyon (most High) shall take the kingdom, and possess the kingdom for ever, even for ever and ever.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Daniel was told what the parable ends on: the saints *shall take the kingdom*. The servants given the goods are the ones who end up holding it, and it is for good, *for ever and ever*. The prophet had it long before Matthew wrote the story down.$n$,13,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:18 — *saints of the El Elyon (most High) shall take the kingdom, and possess the kingdom for ever.* The saints receive the kingdom and keep it for ever, which is what the faithful servants are brought into.$n$),
(2983,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','daniel',7,22,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:22 — *Until the Ancient of days came, and judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Judgment comes first. *Until the Ancient of days came*, the saints did not hold the kingdom; then *judgment was given to the saints* and they possessed it. The coming and the reckoning arrive together here, as they do when the master returns to settle with his servants.$n$,13,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:22 — *judgment was given to the saints of the El Elyon (most High); and the time came that the saints possessed the kingdom.* When the Ancient of days comes, judgment is given to the saints and they possess the kingdom.$n$),
(2984,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','daniel',7,27,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:27 — *And the kingdom and dominion, and the greatness of the kingdom under the whole heaven, shall be given to the people of the saints of the El Elyon (most High), whose kingdom is an everlasting kingdom, and all dominions shall serve and obey him.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) The kingdom is given to *the people of the saints*, and it is *an everlasting kingdom*. The talents were a small thing beside what Daniel saw handed over, the whole kingdom *under the whole heaven*. The servants who held what was given them are the ones it is given to.$n$,13,$n$The saints-of-the-most-High receive-the-kingdom.$n$,$n$Daniel 7:27 — *shall be given to the people of the saints of the El Elyon (most High), whose kingdom is an everlasting kingdom.* The whole kingdom is given to the people of the saints, and it does not end.$n$),
(2985,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','proverbs',6,6,$n$The Tanakh-substance against the slothful.$n$,$n$Proverbs 6:6 — *Go to the ant, thou sluggard; consider her ways, and be wise:* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) A sluggard is told to *go to the ant* and *consider her ways, and be wise*. The servant who hid his talent in the earth is the one who needed that word. He was given a share and did nothing with it. The old writings already had the lazy servant's picture.$n$,13,$n$The Tanakh-substance against the slothful.$n$,$n$Proverbs 6:6 — *Go to the ant, thou sluggard; consider her ways, and be wise.* The sluggard is sent to the ant to learn, and the servant with the buried talent is the one sent.$n$),
(2986,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','proverbs',13,4,$n$The sluggard-soul-desireth-and-hath-nothing.$n$,$n$Proverbs 13:4 — *The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) The sluggard *desireth, and hath nothing*, and that is where the servant with the buried talent ends, with even that taken from him. The diligent *shall be made fat*, which is the other servants, handed more. The proverb had the pair long before the parable.$n$,13,$n$The sluggard-soul-desireth-and-hath-nothing.$n$,$n$Proverbs 13:4 — *The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.* The sluggard ends with nothing and the diligent are made fat, the two ends of the servants.$n$),
(2987,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','1-corinthians',12,4,$n$The diversity-of-gifts substance.$n$,$n$1 Corinthians 12:4 — *Now there are diversities of gifts, but the same Spirit.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Gifts differ, and the giver is the same. The servants are handed his goods in different measures, and every share comes out of the same stock. Paul puts it as *diversities of gifts, but the same Spirit*. What a servant holds is his master's, whatever the size.$n$,13,$n$The diversity-of-gifts substance.$n$,$n$1 Corinthians 12:4 — *there are diversities of gifts, but the same Spirit.* The gifts differ in kind and size, but they all come from one giver.$n$),
(2988,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','romans',12,3,$n$The substantial-stewardship-of-gifts-substance.$n$,$n$Romans 12:3 — *For I say, through the grace given unto me, to every man that is among you, not to think of himself more highly than he ought to think; but to think soberly, according as Elohim (God) hath dealt to every man the measure of faith.* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Paul says Elohim (God) has *dealt to every man the measure*, and no one is to think more of himself than he ought. The servants in the parable each get a share of the goods by measure, and each is answerable for his own share. Nobody is handed everything and nobody is handed nothing.$n$,13,$n$The substantial-stewardship-of-gifts-substance.$n$,$n$Romans 12:3 — *according as Elohim (God) hath dealt to every man the measure of faith.* Each man is dealt a measure, and thinking soberly means owning what he was dealt and no more.$n$),
(2989,'canon','matthew',25,14,$n$For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.$n$,'canon','1-peter',4,10,$n$*Good stewards of the manifold grace.*$n$,$n$1 Peter 4:10 — *As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of Elohim (God).* *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14) Peter puts the parable in one line. The gift is received, and the servant is a steward of it, to *minister the same one to another*. The goods were never his own, and a good steward uses them for the household instead of burying them.$n$,13,$n$*Good stewards of the manifold grace of Elohim (God).*$n$,$n$1 Peter 4:10 — *minister the same one to another, as good stewards of the manifold grace of Elohim (God).* A servant who has received a gift is to spend it on others as a good steward.$n$),
(7080,'canon','luke',18,18,$n$And a certain ruler asked him, saying, Good Master, what shall I do to inherit eternal life?$n$,'canon','matthew',25,14,$n$thread:parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness | The rich-young-ruler — the inverse of the good-and-faithful-servant. The ruler is given the talent (*sell all that thou hast, and distribute unto the poor*, v.22), and walks away sorrowful.$n$,$n$Matthew 25:14 — *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* *And a certain ruler asked him, saying, Good Master, what shall I do to inherit eternal life?* (Luke 18:18) A ruler asks what he must do to inherit. Matthew's parable gives the shape of the answer: a man leaves *his goods* with *his own servants*, and each is held to what he did with them. Doing is the stewarding of what is put in your hands, and it is reckoned when the master comes.$n$,13,$n$The rich-young-ruler — the inverse of the good-and-faithful-servant. The ruler is given the talent (*sell all that thou hast, and distribute unto the poor*, v.22), and walks away sorrowful.$n$,$n$Matthew 25:14 — *travelling into a far country, who called his own servants, and delivered unto them his goods.* The goods left with his own servants are what the ruler's question about doing comes down to.$n$),
(5298,'canon','mark',13,34,$n$For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.$n$,'canon','matthew',24,42,$n$thread:parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness | *Watch ye therefore: for ye know not when the master of the house cometh.* The watch-parable closes the Markan Olivet.$n$,$n$Matthew 24:42 — *Watch therefore: for ye know not what hour your Lord doth come.* *For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.* (Mark 13:34) Mark leaves the porter told *to watch*. Matthew puts the same charge in the mouth of Yahusha (Jesus): *Watch therefore*, for the hour is not known. The servants left with their work are the ones watching for the one who left them.$n$,13,$n$*Watch ye therefore: for ye know not when the master of the house cometh.* The watch-parable closes the Markan Olivet.$n$,$n$Matthew 24:42 — *for ye know not what hour your Lord doth come.* The watch the porter is told to keep is a watch for an hour no one knows.$n$),
(7090,'canon','luke',19,11,$n$And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of Elohim (God) should immediately appear.$n$,'canon','matthew',25,14,$n$thread:parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness | Luke's pounds-parable is a distinct parable from Matt 25's talents, but the trade-the-deposit-and-give-account architecture is the same: the King going to receive a kingdom and returning to reckon what each servant did with what was entrusted.$n$,$n$Matthew 25:14 — *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* *And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of Elohim (God) should immediately appear.* (Luke 19:11) Luke has them thinking the kingdom would *appear* at once. Matthew gives the same kind of story without the nobleman and says plainly what the kingdom is like: a man goes away and leaves *his goods* with *his own servants*. The kingdom is not arriving today. There is a going, and servants given work in between.$n$,13,$n$Luke's pounds-parable is a distinct parable from Matt 25's talents, but the trade-the-deposit-and-give-account architecture is the same: the King going to receive a kingdom and returning to reckon what each servant did with what was entrusted.$n$,$n$Matthew 25:14 — *travelling into a far country, who called his own servants, and delivered unto them his goods.* The kingdom is a man who goes away and leaves his goods with his own servants, not something appearing at once.$n$),
(5299,'canon','mark',13,34,$n$For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.$n$,'canon','matthew',25,14,$n$thread:parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness | The Matthean talents-parable parallel.$n$,$n$Matthew 25:14 — *For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* *For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.* (Mark 13:34) Mark has a man *taking a far journey* who gives *authority to his servants*. Matthew has the same man, *travelling into a far country*, calling *his own servants* and handing over *his goods*. What Mark calls authority and work, Matthew calls goods put in their hands. The servants are his in both.$n$,13,$n$The Matthean talents-parable parallel.$n$,$n$Matthew 25:14 — *a man travelling into a far country, who called his own servants.* The same man goes on the same journey and leaves his own servants with what is his.$n$),
(5300,'canon','mark',13,34,$n$For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.$n$,'canon','luke',12,35,$n$thread:parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness | The Lukan watch-parable parallel.$n$,$n$Luke 12:35 — *Let your loins be girded about, and your lights burning;* *For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.* (Mark 13:34) Mark leaves the porter told to watch. Luke says how it is done: loins *girded about* and *lights burning*. A servant who is ready is dressed and has the lamp lit, so that when his master comes he is not caught asleep.$n$,13,$n$The Lukan watch-parable parallel.$n$,$n$Luke 12:35 — *Let your loins be girded about, and your lights burning.* Watching means being dressed for work with the light on, ready for the master's return.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (13, 'parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness', $n$Parable Of The Talents Stewardship And The Unprofitable Servant Cast Into Outer Darkness$n$, $n$The talents — his own servants, his goods delivered, the reckoning at his coming, and the one cast out (Luke 19; Daniel 7; Proverbs 13; Revelation 2)$n$, $n$**`parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness`** — anchor at Matt 25:14-30. The substantial-substance-of-the-substance-of-the-stewardship-substance + the unprofitable-servant-substance walking the `grace-and-the-opportunity-that-can-be-lost` thread (FREE-TIER-CANDIDATE) at the substantial-substance-of-the-most-substantial-substance — the unprofitable-servant has-been-given-the-talent + has-been-named-as-a-servant + has-been-cast-into-outer-darkness for-the-failure-of-stewardship-substance. 14 members.$n$, $n$It ain't new. A lord who goes away, leaves his goods with his own servants, and comes back to reckon with them: the prophets had the saints taking the kingdom, and the proverbs had the sluggard with nothing, long before Matthew wrote the parable down:

*For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.* (Matthew 25:14)

*And unto one he gave five talents, to another two, and to another one; to every man according to his several ability; and straightway took his journey.* (Matthew 25:15)

Mark who they are. Not strangers, not hired men off the road, but his own servants, each given a share of what is his. Luke tells it with pounds and a nobleman gone to receive a kingdom:

*He said therefore, A certain nobleman went into a far country to receive for himself a kingdom, and to return.* (Luke 19:12)

*And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come.* (Luke 19:13)

Mark has the same house and the same journey, with the charge to watch:

*For the Son of Adam is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.* (Mark 13:34)

Then the lord comes back:

*After a long time the lord of those servants cometh, and reckoneth with them.* (Matthew 25:19)

*His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord.* (Matthew 25:21)

*Then he which had received the one talent came and said, Lord, I knew thee that thou art an hard man, reaping where thou hast not sown, and gathering where thou hast not strawed:* (Matthew 25:24)

*And I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine.* (Matthew 25:25)

*His lord answered and said unto him, Thou wicked and slothful servant, thou knewest that I reap where I sowed not, and gather where I have not strawed:* (Matthew 25:26)

*And cast ye the unprofitable servant into outer darkness: there shall be weeping and gnashing of teeth.* (Matthew 25:30)

The one cast out was given a talent, called a servant, and reckoned with as one of the household. He is not a tare and not one of the nations. He is of the house, and he is judged by what he did with what he was given. Luke says the same of the servant who knew his lord's will:

*And that servant, which knew his lord’s will, and prepared not himself, neither did according to his will, shall be beaten with many stripes.* (Luke 12:47)

And Matthew had already said who it is that ends in outer darkness:

*But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.* (Matthew 8:12)

The proverbs had the slothful man's end long before:

*The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.* (Proverbs 13:4)

*Go to the ant, thou sluggard; consider her ways, and be wise:* (Proverbs 6:6)

What the faithful are given is rule, and Daniel had seen whose that rule is:

*But the saints of the El Elyon (most High) shall take the kingdom, and possess the kingdom for ever, even for ever and ever.* (Daniel 7:18)

*And the kingdom and dominion, and the greatness of the kingdom under the whole heaven, shall be given to the people of the saints of the El Elyon (most High), whose kingdom is an everlasting kingdom, and all dominions shall serve and obey him.* (Daniel 7:27)

The twelve thrones and the reign on the earth are that same rule, promised to the same servants, and the one who gets it is the one who keeps his works to the end:

*And Yahusha (Jesus) said unto them, Verily I say unto you, That ye which have followed me, in the regeneration when the Son of Adam shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar'el (Israel).* (Matthew 19:28)

*And he that overcometh, and keepeth my works unto the end, to him will I give power over the nations:* (Revelation 2:26)

*And hast made us unto our Elohim (God) kings and priests: and we shall reign on the earth.* (Revelation 5:10)

The talents are the gifts, dealt to each by measure, and Peter says what a servant does with a gift:

*As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of Elohim (God).* (1 Peter 4:10)

*For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath.* (Matthew 25:29)

The reckoning is of the house, by works, at his coming. The one with his talent in the ground was no stranger, and the door he is put out of was his own lord's. So the parable ends where the chapter before it did:

*Watch therefore: for ye know not what hour your Lord doth come.* (Matthew 24:42)$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 13 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 13 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (parable-of-the-talents) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — parable-of-the-talents done.'
